using System.Globalization;
using PosNfce.Fiscal.Domain.Issuers;
using PosNfce.Fiscal.Domain.Taxes;
using PosNfce.SharedKernel;

namespace PosNfce.Fiscal.Domain.Documents;

/// <summary>NF-e payment method (<c>tPag</c>). Cards and PIX also carry the card group with the integration type.</summary>
public enum NfcePaymentKind
{
    Cash = 1,
    CreditCard = 3,
    DebitCard = 4,

    /// <summary>"Pagamento instantâneo (PIX) – dinâmico": the QR Code is generated by the terminal for this sale.</summary>
    Pix = 17,
}

public sealed record NfcePayment(NfcePaymentKind Kind, Money Amount, bool Integrated)
{
    public bool HasCardGroup => Kind != NfcePaymentKind.Cash;
}

public sealed record NfceItem(FiscalItem Item, string Description, ItemTaxes Taxes);

public sealed record NfceTotals(
    Money Products, Money Discount, Money Total, Money Pis, Money Cofins, ApproximateTaxes Approximate,
    Money? IbsCbsBase, Money? IbsState, Money? IbsMunicipal, Money? Cbs)
{
    public bool HasIbsCbs => IbsCbsBase is not null;
}

/// <summary>
/// Everything needed to write one NFC-e, already decided: number, taxes per item, totals, payments and the text
/// for the consumer. The adapter only translates it into the library's XML classes.
/// </summary>
public sealed record NfceDraft(
    Guid DocumentId,
    int Series,
    long Number,
    string NumericCode,
    DateTimeOffset IssuedAt,
    bool Homologation,
    IssuerProfile Issuer,
    IReadOnlyList<NfceItem> Items,
    NfceTotals Totals,
    IReadOnlyList<NfcePayment> Payments,
    Money Change,
    string AdditionalInfo,
    string? CustomerCpf)
{
    /// <summary>In homologation SEFAZ requires this exact description in the first item.</summary>
    public const string HomologationDescription = "NOTA FISCAL EMITIDA EM AMBIENTE DE HOMOLOGACAO - SEM VALOR FISCAL";

    public static NfceDraft Build(
        FiscalDocument document, IssuerProfile issuer, IReadOnlyList<ItemTaxes> taxes,
        DateTimeOffset issuedAt, bool homologation, string numericCode, string? approximateSource)
    {
        if (document.Series is not { } series || document.Number is not { } number)
        {
            throw new DomainException("A nota precisa de série e número antes de ser montada.");
        }

        if (taxes.Count != document.Items.Count)
        {
            throw new InvalidOperationException("One ItemTaxes per document item is required.");
        }

        if (numericCode.Length != 8 || !numericCode.All(char.IsAsciiDigit))
        {
            throw new DomainException("Código numérico da nota (cNF) deve ter 8 dígitos.");
        }

        var items = document.Items
            .Select((item, i) => new NfceItem(
                item, homologation && i == 0 ? HomologationDescription : item.Description, taxes[i]))
            .ToList();

        var approximate = taxes.Aggregate(ApproximateTaxes.None, (sum, t) => sum + t.Approximate);
        var ibsCbs = taxes.Where(t => t.IbsCbs is not null).Select(t => t.IbsCbs!).ToList();
        var totals = new NfceTotals(
            document.GrossTotal,
            document.Discount,
            document.Total,
            Sum(taxes.Select(t => t.Pis.Value)),
            Sum(taxes.Select(t => t.Cofins.Value)),
            approximate,
            ibsCbs.Count == 0 ? null : Sum(ibsCbs.Select(t => t.Base)),
            ibsCbs.Count == 0 ? null : Sum(ibsCbs.Select(t => t.IbsState)),
            ibsCbs.Count == 0 ? null : Sum(ibsCbs.Select(t => t.IbsMunicipal)),
            ibsCbs.Count == 0 ? null : Sum(ibsCbs.Select(t => t.Cbs)));

        return new NfceDraft(
            document.Id, series, number, numericCode, issuedAt, homologation, issuer, items, totals,
            document.Payments.Select(Payment).ToList(), document.Change, ApproximateTaxesText(approximate, approximateSource),
            document.CustomerCpf);
    }

    private static Money Sum(IEnumerable<Money> values) => values.Aggregate(Money.Zero, (sum, v) => sum + v);

    private static NfcePayment Payment(FiscalPayment payment) => new(
        payment.Method switch
        {
            "Cash" => NfcePaymentKind.Cash,
            "CreditCard" => NfcePaymentKind.CreditCard,
            "DebitCard" => NfcePaymentKind.DebitCard,
            "Pix" => NfcePaymentKind.Pix,
            _ => throw new DomainException($"Forma de pagamento \"{payment.Method}\" sem código na NFC-e."),
        },
        payment.Amount,
        payment.Integrated);

    /// <summary>Lei 12.741/2012: approximate taxes by sphere and the source of the rates, in the additional information.</summary>
    private static string ApproximateTaxesText(ApproximateTaxes approximate, string? source)
    {
        if (approximate.Total == Money.Zero)
        {
            return "";
        }

        var brazilian = CultureInfo.GetCultureInfo("pt-BR");
        string Value(Money m) => m.Amount.ToString("0.00", brazilian);
        return $"Trib aprox R$ {Value(approximate.Federal)} Federal, R$ {Value(approximate.State)} Estadual"
            + $" e R$ {Value(approximate.Municipal)} Municipal. Fonte: {source ?? "IBPT"}";
    }
}
